-- Variétés des espèces : nom, particularités (traits), délai jusqu'à la récolte propre à la variété, conseils.
create table public.varieties (
  id uuid primary key default gen_random_uuid(),
  species_id uuid not null references public.species(id) on delete cascade,
  slug text not null,
  name text not null,
  days_to_harvest int check (days_to_harvest is null or days_to_harvest > 0),
  traits text[] not null default '{}',
  notes text,
  sort int not null default 0,
  unique (species_id, slug)
);
create index varieties_species_idx on public.varieties(species_id);
alter table public.varieties enable row level security;
create policy "variétés lisibles" on public.varieties for select to anon, authenticated using (true);

-- Une plantation garde sa variété, et recopie ce qui la distingue (délai de récolte) : une valeur propre à la plantation l'emporte sur celle de l'espèce
alter table public.plantings
  add column variety_id uuid references public.varieties(id) on delete set null,
  add column days_to_harvest int check (days_to_harvest is null or days_to_harvest > 0);

insert into public.varieties (species_id, slug, name, days_to_harvest, traits, notes, sort)
